import * as M from './model.js';
import * as Network from './staff-network.js';
import * as A from './academic-year.js';
import * as P from './planner.js';
import * as W from './staff-work.js';
import * as People from './community-life.js';
export const PLEDGES=[['library','책을 찾기 쉬운 도서관','서가 안내를 학생 눈높이로 바꾸고 사서교사와 확인합니다.'],['voice','작은 의견도 모으기','글·그림 제안함을 두고 매달 답변을 공유합니다.'],['play','모두 참여하는 놀이','쉬는 시간 놀이를 희망 조사하고 도구 사용 차례를 정합니다.'],['environment','함께 쓰는 공간','물품 상태를 살피고 학교 담당자에게 필요한 점검을 요청합니다.']];
const hash=t=>String(t).split('').reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,19);
export function data(s){return s.democracy??={schema:1,elections:[],committee:[],volunteers:[],history:[]};}
export function roll(s,voterGrade=3){const list=[],classes=M.REGIONS[s.config.region].classes,n=M.REGIONS[s.config.region].count,ourClass=classes===1?1:2;for(let grade=voterGrade;grade<=6;grade++)for(let room=1;room<=classes;room++){if(grade===s.config.grade&&room===ourClass){for(const st of s.students)list.push({key:st.personKey||st.id,name:st.name,grade,room,classmate:true,studentId:st.id});}else for(let i=0;i<n;i++)list.push({key:`school-${s.academic.year}-${grade}-${room}-${i}`,name:['김','이','박','최','정','강','윤','조'][i%8]+['하람','가온','마루','서우','다솔','시온','유림','나래','예담','도하','소윤','지한'][(Math.floor(i/8)+room+grade)%12],grade,room,classmate:false});}return list;}
export function current(s){return data(s).elections.find(e=>e.year===s.academic.year&&e.term===A.term(s));}
export function start(s,voterGrade=3,candidateGrade=5){if(current(s))return {error:'이번 학기 선거가 이미 있습니다.'};if(![1,2,3,4].includes(voterGrade)||![4,5,6].includes(candidateGrade)||candidateGrade<voterGrade)return false;const voters=roll(s,voterGrade);data(s).elections.push({id:'election-'+s.academic.year+'-'+A.term(s),year:s.academic.year,term:A.term(s),voterGrade,candidateGrade,voters,candidates:[],stage:'nomination',campaign:[],ballots:[],result:null,created:M.stamp(s)});return {ok:true};}
export function candidates(s){const e=current(s);return e?e.voters.filter(v=>v.grade>=e.candidateGrade):[];}
export function nominate(s,key,pledge){const e=current(s),candidate=candidates(s).find(v=>v.key===key);if(!e||e.stage!=='nomination'||!candidate||!PLEDGES.some(x=>x[0]===pledge)||e.candidates.length>=5||e.candidates.some(x=>x.key===key))return {error:'희망 후보 1~5명과 실천 가능한 공약을 선택해 주세요.'};e.candidates.push({...candidate,pledge,voluntary:true});return {ok:true};}
export function remove(s,key){const e=current(s);if(!e||e.stage!=='nomination')return false;e.candidates=e.candidates.filter(c=>c.key!==key);return {ok:true};}
function time(s,minutes){const slot=M.currentSlot(s);return !s.staffWork?.away&&!M.movementBusy(s)&&slot.end-s.minute>=minutes&&!P.conflicts(s,s.day,s.minute,s.minute+minutes).length&&(W.free(s,minutes)||slot.kind==='lesson'&&slot.subject==='창체');}
export function campaign(s,mode){const e=current(s);if(!e||!['nomination','campaign'].includes(e.stage)||e.candidates.length<1||!['poster','debate','accessible'].includes(mode))return {error:'희망 후보 등록 후 선거운동 방법을 선택해 주세요.'};if(e.campaign.some(x=>x.mode===mode))return {error:'이 선거운동은 이미 진행했습니다.'};if(!time(s,10))return {error:'선거 활동을 진행할 10분을 확보해 주세요.'};M.advance(s,10);e.stage='campaign';e.campaign.push({mode,date:M.stamp(s),speeches:e.candidates.map(c=>({key:c.key,text:mode==='debate'?'공약을 실천하려면 필요한 시간과 담당자의 협의를 먼저 확인하겠습니다.':PLEDGES.find(p=>p[0]===c.pledge)[2]}))});return {ok:true};}
export function vote(s){const e=current(s);if(!e||e.stage!=='campaign'||e.campaign.length<2)return {error:'공약 소개와 질의 등 서로 다른 선거운동 2가지를 마쳐 주세요.'};if(!time(s,15))return {error:'투표 안내·개표에 15분이 필요합니다.'};const counts=Object.fromEntries(e.candidates.map(c=>[c.key,0]));e.ballots=e.voters.map(v=>{if(v.classmate&&(!s.students.some(st=>st.id===v.studentId)||!M.isPresent(s,v.studentId)))return {voter:v.key,status:'absent',choice:null};const n=hash(e.id+'-'+v.key),preferred=PLEDGES[n%PLEDGES.length][0];if(n%23===0)return {voter:v.key,status:'abstain',choice:null};const ranked=e.candidates.map(c=>({key:c.key,weight:(c.pledge===preferred?40:0)+hash(v.key+c.key)%31+e.campaign.length*3})).sort((a,b)=>b.weight-a.weight||a.key.localeCompare(b.key));const choice=ranked[0].key;counts[choice]++;return {voter:v.key,status:'valid',choice};});const max=Math.max(...Object.values(counts));e.result={counts,winners:max>0?Object.keys(counts).filter(key=>counts[key]===max):[],eligible:e.voters.length,cast:e.ballots.filter(b=>b.status!=='absent').length,abstain:e.ballots.filter(b=>b.status==='abstain').length,absent:e.ballots.filter(b=>b.status==='absent').length,rule:'게임 학교 자치 규칙: 동점 최다 득표자는 공동대표'};e.stage='result';M.advance(s,15);e.completed=M.stamp(s);M.addMessage(s,'all','학생회 담당교사','개별 투표를 집계한 전교 선거 결과를 게시했습니다. 표의 내용은 비공개이며 전체 집계만 확인합니다.',{senderId:'colleague',plannerScanned:true});return {ok:true};}
export function committeeElection(s,stand){const d=data(s);if(d.committee.some(x=>x.year===s.academic.year))return {error:'이번 학년도 위원 선출을 이미 진행했습니다.'};if(!W.free(s,20))return {error:'수업 밖 20분이 필요합니다.'};const staff=M.NPCS.filter(n=>['teacher','colleague','specialist','librarian','nurse'].includes(n.id)&& (n.id!=='teacher'||stand));const votes=Object.fromEntries(staff.map(n=>[n.id,0])),ballots=M.NPCS.filter(n=>n.id!=='admin'&&n.id!=='neulbom').map(n=>{const choice=staff[hash(n.id+s.academic.year)%staff.length].id;votes[choice]++;return {voter:n.id,choice};});const sorted=staff.map(n=>({...n,votes:votes[n.id]})).sort((a,b)=>b.votes-a.votes||a.id.localeCompare(b.id)),elected=sorted.slice(0,2).map(n=>n.id);const guardians=Object.values(People.data(s).guardians).filter(g=>People.children(s,g).some(st=>g.permissions[st.personKey]?.verified));const parentVotes=Object.fromEntries(guardians.slice(0,4).map(g=>[g.key,0]));for(const g of guardians)if(Object.keys(parentVotes).length)parentVotes[Object.keys(parentVotes)[hash(g.key)%Object.keys(parentVotes).length]]++;const parents=Object.entries(parentVotes).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([key])=>key);const row={year:s.academic.year,ballots,votes,elected,parents,parentVotes,regional:'선출 위원의 추천·동의 후 지역 협력위원 1명 위촉',date:M.stamp(s),rule:'가상 학교 규칙: 교원 2·학부모 2·지역 1, 동점은 사전 공지 후보 순서'};d.committee.push(row);W.data(s).committeeMember=elected.includes('teacher');M.advance(s,20);return {ok:true};}
export function volunteer(s,kind,parentKey,day,start,end){const d=data(s),g=People.guardian(s,parentKey);if(!['학부모회','등하굣길 안전 봉사'].includes(kind)||!g||!A.schoolDay(s,day)||day<s.day||!Number.isInteger(start)||!Number.isInteger(end)||start<520||end>1000||end-start<10)return {error:'희망 보호자와 앞으로의 등교일·활동 시간을 확인해 주세요.'};if(d.volunteers.some(v=>v.parentKey===g.key&&v.day===day&&v.status==='예정'&&v.start<end&&start<v.end))return {error:'같은 보호자의 다른 봉사 일정과 겹칩니다.'};d.volunteers.push({id:'volunteer-'+d.volunteers.length,kind,parentKey:g.key,name:g.name,day,start,end,status:'예정',replacement:null,voluntary:true,studentPenalty:0,date:M.stamp(s)});return {ok:true};}
export function replaceVolunteer(s,id,key){const v=data(s).volunteers.find(x=>x.id===id),g=People.guardian(s,key);if(!v||v.status!=='예정'||v.day<s.day)return false;if(key!=='school'&&!g)return {error:'대체 희망자 또는 학교 지원을 선택해 주세요.'};if(g&&data(s).volunteers.some(x=>x.id!==id&&x.parentKey===g.key&&x.day===v.day&&x.status==='예정'&&x.start<v.end&&v.start<x.end))return {error:'대체 희망자의 일정이 겹칩니다.'};v.status='취소';v.cancelled=M.stamp(s);if(key==='school'){Network.requestCover(s,v);v.replacement='학교 지원 인력 요청';M.addMessage(s,'all','나',M.dateLabel({day:v.day})+' '+v.kind+' 학교 지원 인력을 요청합니다.',{senderId:'teacher',recipientId:'principal'});}else if(g){const r=volunteer(s,v.kind,g.key,v.day,v.start,v.end);if(r?.error){v.status='예정';return r;}v.replacement=g.name;}else return {error:'대체 희망자 또는 학교 지원을 선택해 주세요.'};return {ok:true};}
export function valid(s){
 const d=s.democracy;if(d==null)return true;const arr=Array.isArray,txt=v=>typeof v==='string'&&v.length<=2000&&!/[<>]/.test(v),unique=(rows,key)=>new Set(rows.map(x=>x[key])).size===rows.length;
 function election(e){
  if(!Number.isInteger(e.year)||![1,2].includes(e.term)||![1,2,3,4].includes(e.voterGrade)||![4,5,6].includes(e.candidateGrade)||!['nomination','campaign','result'].includes(e.stage)||!arr(e.voters)||!unique(e.voters,'key')||!e.voters.every(v=>txt(v.key)&&txt(v.name)&&Number.isInteger(v.grade)&&v.grade>=e.voterGrade&&v.grade<=6)||!arr(e.candidates)||e.candidates.length>5||!unique(e.candidates,'key')||!e.candidates.every(c=>e.voters.some(v=>v.key===c.key&&v.grade>=e.candidateGrade)&&PLEDGES.some(p=>p[0]===c.pledge))||!arr(e.campaign)||!unique(e.campaign,'mode')||!e.campaign.every(c=>['poster','debate','accessible'].includes(c.mode)&&arr(c.speeches))||!arr(e.ballots))return false;
  if(e.stage!=='result')return e.result===null&&e.ballots.length===0;
  if(!e.result||!e.candidates.length||e.campaign.length<2||e.ballots.length!==e.voters.length||!unique(e.ballots,'voter')||!e.ballots.every(b=>e.voters.some(v=>v.key===b.voter)&&['absent','abstain','valid'].includes(b.status)&&(b.status==='valid'?e.candidates.some(c=>c.key===b.choice):b.choice===null)))return false;
  const r=e.result,counts=Object.fromEntries(e.candidates.map(c=>[c.key,e.ballots.filter(b=>b.status==='valid'&&b.choice===c.key).length])),max=Math.max(...Object.values(counts)),winners=max>0?Object.keys(counts).filter(k=>counts[k]===max):[];
  return Object.keys(r.counts||{}).length===e.candidates.length&&Object.entries(counts).every(([k,n])=>r.counts[k]===n)&&r.eligible===e.voters.length&&r.absent===e.ballots.filter(b=>b.status==='absent').length&&r.abstain===e.ballots.filter(b=>b.status==='abstain').length&&r.cast===e.voters.length-r.absent&&arr(r.winners)&&[...r.winners].sort().join('|')===winners.sort().join('|');
 }
 return d.schema===1&&arr(d.elections)&&unique(d.elections,'id')&&d.elections.every(election)&&arr(d.committee)&&d.committee.every(c=>Number.isInteger(c.year)&&arr(c.ballots)&&unique(c.ballots,'voter')&&arr(c.elected)&&c.elected.length===2&&c.elected.every(k=>Object.hasOwn(c.votes,k))&&Object.entries(c.votes).every(([k,n])=>n===c.ballots.filter(b=>b.choice===k).length)&&arr(c.parents)&&c.parents.every(k=>!!s.community?.guardians[k]))&&arr(d.volunteers)&&d.volunteers.every(v=>txt(v.name)&&!!s.community?.guardians[v.parentKey]&&Number.isInteger(v.day)&&v.day>=0&&Number.isInteger(v.start)&&Number.isInteger(v.end)&&v.start>=520&&v.end<=1000&&v.start<v.end&&['예정','취소','완료'].includes(v.status)&&v.voluntary===true&&v.studentPenalty===0)&&arr(d.history);
}
